export function resolveLanguage(preference = 'auto', hostLanguage) {
 if (preference === 'zh' || preference === 'en') return preference;
 if (!hostLanguage) return 'zh';
 return hostLanguage.toLowerCase().startsWith('zh') ? 'zh' : 'en';
}

